var REPORT_SKILL_AR={"Reading": "القراءة", "Vocabulary": "المفردات", "Grammar": "القواعد", "Writing": "الكتابة", "Number & Operations": "الأعداد والعمليات", "Algebra": "الجبر", "Geometry": "الهندسة", "Data & Probability": "البيانات والاحتمالات", "Measurement & Units": "القياس والوحدات", "Motion & Forces": "الحركة والقوى", "Waves & Sound": "الموجات والصوت", "Light & Optics": "الضوء والبصريات", "Life Science": "علوم الحياة", "Physical Science": "العلوم الفيزيائية", "Earth & Space Science": "علوم الأرض والفضاء", "Scientific Inquiry & Technology": "الاستقصاء العلمي والتكنولوجيا", "Matter & Atomic Structure": "المادة والتركيب الذري", "Bonding & Compounds": "الروابط والمركبات", "Reactions & Stoichiometry": "التفاعلات والحسابات الكيميائية", "States, Solutions & Organic": "حالات المادة والمحاليل والكيمياء العضوية", "Chemistry of Life": "كيمياء الحياة", "Cells & Energy": "الخلايا والطاقة", "Human Body & Health": "جسم الإنسان والصحة", "Plants & Ecology": "النباتات والبيئة", "Genetics & Heredity": "الوراثة"};
var STRATEGIES_AR={"Reading": {"support": ["<b>الإملاء المتنقّل</b> — يُعلَّق نص قصير على الجدار؛ يقرأ الطلاب العدّاؤون النص ويحفظونه ويُملونه على زميل الكتابة، ثم يتحققون منه.", "<b>بطاقات ترتيب أحداث القصة</b> — يرتّب الطلاب في أزواج شرائط جمل مبعثرة من قصة قصيرة بالترتيب الصحيح.", "<b>البحث بقلم التظليل</b> — يُقدَّم نص من 4–5 أسطر ويتسابق الطلاب لوضع خط تحت إجابة سؤال حرفي («أشِر إلى الكلمات»).", "<b>Kahoot! / Blooket «صواب أم خطأ»</b> — أسئلة سريعة للتحقق من الفهم حول نص قصير قرأه الصف معًا."], "extend": ["<b>القراءة التشاركية (Jigsaw)</b> — تقرأ كل مجموعة نصًا قصيرًا مختلفًا، ثم تشرحه للمجموعات الأخرى وتقارن الأفكار.", "<b>أدوار القراءة التبادلية</b> — تتناوب المجموعة على أدوار المتنبّئ والسائل والموضّح والملخّص.", "<b>مناظرة النصّين</b> — يقرأ الطلاب رأيين حول موضوع واحد ويناقشون أيهما أكثر إقناعًا مستخدمين الأدلة."]}, "Vocabulary": {"support": ["<b>لعبة مضرب الذباب</b> — تُكتب الكلمات على السبورة؛ يتسابق طالبان لضرب الكلمة التي يعرّفها المعلم.", "<b>الرسم والتمثيل الصامت</b> — يمثّل الطالب الكلمة المستهدفة أو يرسمها ليخمّنها فريقه.", "<b>جدار الكلمات + لعبة البنغو</b> — يبني الصف جدارًا للكلمات، ثم يلعب الطلاب بنغو التعريفات باستخدام تلك الكلمات.", "<b>Wordwall.net «المطابقة»</b> أو <b>Quizlet Live</b> — مطابقة الكلمات بمعانيها ضمن فرق."], "extend": ["<b>سلالم المترادفات</b> — الارتقاء من كلمة ضعيفة إلى كلمة أقوى (big → large → enormous).", "<b>دفتر المفردات + نموذج فراير</b> — الكلمة، والمعنى، ومثال، ومثال مضاد، وصورة.", "<b>لعبة الكلمات المحظورة (Taboo)</b> — يصف الطالب كلمة لفريقه دون أن يذكر الكلمات «المحظورة»."]}, "Grammar": {"support": ["<b>سباق ترتيب الجملة</b> — تعيد الفرق ترتيب بطاقات كلمات مقصوصة لتكوين جملة صحيحة.", "<b>الزوايا الأربع</b> — تُسمّى زوايا الصف A/B/C/D؛ يجري الطلاب إلى الزاوية التي تحمل صيغة الفعل الصحيحة.", "<b>سباق القواعد على السبورة</b> — يتسابق فريقان لتصحيح جملة خاطئة مكتوبة على السبورة.", "<b>Kahoot! / Quizizz</b> — جولات سريعة لـ«اختيار الكلمة الصحيحة» مع تغذية راجعة فورية."], "extend": ["<b>البحث عن الأخطاء وتصحيحها</b> — فقرة تحتوي على أخطاء متنوعة يصحّحها الطلاب باستخدام قائمة تحقق.", "<b>تتابع تحويل الجمل</b> — تغيير زمن الفعل أو التحويل بين المبني للمعلوم والمبني للمجهول على امتداد الصف.", "<b>مزاد القواعد</b> — «تشتري» الفرق الجمل التي تعتقد أنها صحيحة."]}, "Writing": {"support": ["<b>بدايات الجمل + إطار الفقرة</b> — يقدّم المعلم نموذجًا، ثم تُكتب فقرة جماعيًا، ثم يحاول الطلاب بمفردهم.", "<b>القصة بالنرد</b> — يحدّد النرد الشخصية والمكان والمشكلة؛ ويكتب الطالب 3–4 جمل.", "<b>إشارات المرور لعلامات الترقيم</b> — يرفع الطلاب بطاقات حمراء/خضراء لاكتشاف الأحرف الكبيرة أو النقاط المفقودة.", "<b>الإملاء التعاوني (Dictogloss)</b> — يُقرأ نص قصير مرتين؛ يعيد الطلاب بناءه، ثم يقارنون ويصحّحون."], "extend": ["<b>تحرير الأقران باستخدام سلّم تقدير (نجمتان وأمنية)</b> — يقدّم الطلاب ملاحظتي إشادة واقتراحًا واحدًا للتحسين.", "<b>جولة المعرض</b> — تُعرض الفقرات؛ ويترك الزملاء تغذية راجعة على أوراق لاصقة.", "<b>تحدي أدوات الربط</b> — إعادة كتابة فقرة بإضافة first/however/finally لتحسين الانسيابية."]}, "Number & Operations": {"support": ["<b>حول العالم</b> — منافسة ثنائية ببطاقات الحقائق العددية تنتقل بين طلاب الصف.", "<b>خط الأعداد / مكعبات القيمة المنزلية</b> — بناء العدد بصورة محسوسة قبل الانتقال إلى العملية المجرّدة.", "<b>بطاقات المهام المتنقلة (SCOOT)</b> — توزَّع البطاقات في أرجاء الصف؛ ويتنقل الطلاب لحل خطوة واحدة في كل بطاقة.", "<b>Blooket / Prodigy</b> — تدريب على الحقائق والعمليات الحسابية بأسلوب الألعاب."], "extend": ["<b>محطات الرياضيات الحياتية</b> — مسائل التسوق والوصفات والقياس؛ مع شرح طريقة الحل.", "<b>جرّة التقدير / «أيّهما أكبر؟»</b> — التقدير ثم التحقق والتبرير.", "<b>غرفة الهروب الرياضية</b> — حل مسائل متعددة الخطوات لفتح الدليل التالي."]}, "Algebra": {"support": ["<b>معادلات الميزان</b> — استخدام ميزان محسوس أو مرسوم لإيجاد قيمة المجهول.", "<b>بنغو العدد المفقود</b> — حل معادلات بسيطة لتعليم خانات اللوحة.", "<b>قطارات الأنماط</b> — بناء أنماط عددية/شكلية وإكمالها باستخدام العدّادات."], "extend": ["<b>Desmos / تحديات التمثيل البياني</b> — مطابقة المعادلات بالمستقيمات.", "<b>تتابع المعادلات ذات الخطوتين</b> — تحل الفرق المعادلة وتمرّرها إلى العضو التالي.", "<b>«خمّن قاعدتي»</b> — جداول المدخلات/المخرجات التي يكتشف فيها الطلاب القاعدة ويبرّرونها."]}, "Geometry": {"support": ["<b>اللوحة الهندسية / ورق المربعات</b> — عدّ المربعات لإيجاد المساحة والمحيط.", "<b>تصنيف الأشكال والبحث عنها</b> — تصنيف الأشكال ثنائية الأبعاد والبحث عنها في أرجاء الصف.", "<b>تمثيل الزوايا</b> — استخدام الجسم أو الذراعين لتمثيل الزوايا الحادة / القائمة / المنفرجة."], "extend": ["<b>الأوريغامي / الشبكات</b> — بناء مجسمات ثلاثية الأبعاد وحساب المساحة السطحية أو الحجم.", "<b>استقصاء نظرية فيثاغورس</b> — قياس مثلثات قائمة حقيقية واختبار a²+b²=c².", "<b>تصميم مخطط أرضي</b> — تطبيق المساحة والمحيط على مكان حقيقي."]}, "Data & Probability": {"support": ["<b>استبيان الصف + التمثيل بالأعمدة</b> — جمع بيانات حقيقية (الفاكهة المفضلة) وتمثيلها بيانيًا معًا.", "<b>تصنيف المرجّح / غير المرجّح</b> — ترتيب أحداث يومية على خط الاحتمال.", "<b>تجارب النرد والعملة</b> — التنبؤ، ثم رمي النرد/قلب العملة، والتسجيل بالإشارات والمقارنة."], "extend": ["<b>مختبر احتمالات القرص الدوّار</b> — تصميم أقراص دوّارة تحقق احتمالًا معطى في صورة كسر.", "<b>محقّق البيانات</b> — تفسير رسوم بيانية حقيقية من الأخبار/الرياضة واستخلاص الاستنتاجات.", "<b>محطات الوسط الحسابي/الوسيط/المدى</b> — التنقل بين مجموعات بيانات صغيرة والمقارنة بينها."]}, "Measurement & Units": {"support": ["<b>محطات قياس الغرفة</b> — تتنقل مجموعات صغيرة بين المساطر والمخابير المدرّجة والموازين وساعات الإيقاف، وتسجّل القراءات بالوحدات الصحيحة، ويتحقق الطلاب من قراءات بعضهم للتدريج مقارنةً بمفتاح الإجابة لدى المعلم.", "<b>سلّم تحويل الوحدات</b> — استخدام بطاقة مكتبية على شكل سلّم للبادئات من «كيلو» إلى «ملّي» ليصعد الطلاب أو ينزلوا، مع الضرب أو القسمة على قوة العشرة الصحيحة.", "<b>التلاشي التدريجي للأمثلة المحلولة</b> — عرض حل نموذجي كامل لمسألتين في تحويل وحدات النظام الدولي والأرقام المعنوية، ثم حذف خطوة في كل مرة حتى يُكمل الطلاب التحويل كاملًا باستقلالية مع تغذية راجعة.", "<b>بطاقة الخروج: قدِّر ثم قِس</b> — يقدّر الطلاب طول جسم في الصف أو كتلته أو حجمه، ثم يقيسونه ويحسبون نسبة الخطأ المئوية على بطاقة سريعة تُراجَع قبل مغادرة الصف."], "extend": ["<b>استقصاء عدم اليقين</b> — يكرّر الطلاب قياس زمن تأرجح البندول، ويحسبون المتوسط والمدى وعدم اليقين المطلق، ثم يبرّرون أي أداة وطريقة تعطي النتيجة الأدق في تقرير مختبر قصير.", "<b>تحدي تحليل الأبعاد</b> — استخدام الوحدات الأساسية في النظام الدولي للتحقق من الاتساق البُعدي لصيغ فيزيائية معطاة، واشتقاق وحدات كميات غير مألوفة مثل الضغط أو القدرة.", "<b>تدقيق الوحدات في الواقع</b> — يبحث الطلاب في سياق إماراتي في مجال البناء أو الطيران تكون فيه أخطاء الوحدات مؤثرة، ومثال ذلك المسبار Mars Climate Orbiter، ويعرضون قائمة تحقق وقائية على زملائهم.", "<b>مدرّب الدقة من الأقران</b> — يصمّم الطلاب المتمكّنون اختبار Quizizz من خمسة أسئلة حول البادئات وقراءة التدريج والأرقام المعنوية، ثم يقودون جلسة مراجعة قصيرة لمجموعة متعثّرة."]}, "Motion & Forces": {"support": ["<b>التلاشي التدريجي للأمثلة المحلولة</b> — عرض حل نموذجي خطوة بخطوة لمسألتين في السرعة والمسافة والزمن، ثم حذف خطوة في كل مرة حتى يحل الطلاب باستقلالية.", "<b>تجربة العربة والمنحدر</b> — يدحرج الطلاب عربة على منحدرات بارتفاعات مختلفة، ويقيسون زمنها عبر مسافات محددة، ويرسمون تمثيلات بيانية بسيطة للمسافة–الزمن للتمييز بين السرعة الثابتة والتسارع.", "<b>قوالب مخطط الجسم الحر</b> — تقديم مخططات قوى مرسومة جزئيًا مع بطاقات أسهم مُعنونة للوزن والقوة العمودية والاحتكاك وقوة الدفع، ليحدد الطلاب القوى المتزنة وغير المتزنة قبل إجراء الحسابات.", "<b>مطابقة التمثيلات البيانية باستخدام PhET</b> — استخدام محاكاة PhET للقوى والحركة في أزواج، والتنبؤ بالتمثيل البياني للحركة أولًا، ثم التحقق منه وشرح أي اختلاف للمعلم."], "extend": ["<b>موجز تصميم قوانين نيوتن</b> — تصمّم الفرق سيارة تعمل بالبالون وتختبرها، مستخدمةً F = ma والتسارع المَقيس لتفسير أثر تغيّر الكتلة وقوة الدفع في الأداء.", "<b>تحليل تمثيلات السرعة المتجهة–الزمن</b> — يحسب الطلاب التسارع من الميل والإزاحة من المساحة تحت تمثيلات بيانية معقدة متعددة المراحل للسرعة المتجهة–الزمن، ثم يكتبون وصفًا للحركة في كل جزء.", "<b>استقصاء السلامة المرورية</b> — دراسة مسافة التوقف وزمن رد الفعل وقوة الكبح باستخدام حدود السرعة في دولة الإمارات، وإعداد إنفوجرافيك قائم على الأدلة يوضح أهمية مسافات الأمان بين المركبات.", "<b>صائدو المفاهيم الخاطئة</b> — يكتب الطلاب المتمكّنون خيارات مضلِّلة في Kahoot مبنية على أخطاء شائعة مثل «الحركة تحتاج إلى قوة ثابتة»، ثم يشرحون المفهوم الفيزيائي الصحيح بعد كل سؤال."]}, "Waves & Sound": {"support": ["<b>عرض الموجات بالنابض (Slinky)</b> — يمدّ الطلاب في أزواج نابضًا لتكوين موجات مستعرضة وطولية، ويعنونون الطول الموجي والسعة والتضاغط والتخلخل على أوراق لاصقة مثبتة على امتداد النابض.", "<b>منظّم تركيب الموجة</b> — يُكمل الطلاب مخططًا مُعنونًا للموجة وجدولًا من ثلاثة أعمدة يربط السعة بشدة الصوت، والتردد بدرجة الصوت، والطول الموجي بالمسافة بين القمم.", "<b>دعامة معادلة الموجة</b> — تقديم مثلث الصيغة v = fλ مع مربعات وحدات مرمّزة بالألوان، ثم أسئلة تدريب موجّه تتدرج من التعويض المباشر إلى إعادة ترتيب الصيغة لإيجاد التردد.", "<b>التحقق بتصنيف الأصوات</b> — تشغيل نغمات من مولّد نغمات إلكتروني بينما يرفع الطلاب بطاقات تدل على درجة صوت أعلى أو أخفض وصوت أعلى شدة أو أهدأ، مع تغذية راجعة فورية."], "extend": ["<b>تجربة سرعة الصوت</b> — يقيس الطلاب سرعة الصوت باستخدام طريقة الصدى أو طريقة الميكروفونين، ويحسبون النتيجة، ويقيّمون مصادر الخطأ مقارنةً بالقيمة المعتمدة.", "<b>تحليل راسم الإشارات (Oscilloscope)</b> — استخدام تطبيق مجاني لراسم الإشارات على الهاتف لالتقاط أشكال موجات آلات وأصوات مختلفة، ومقارنة التردد والسعة وشكل الموجة لتفسير نوع الصوت (الجرس الصوتي).", "<b>مشروع التحكم في الضوضاء</b> — تستقصي المجموعات مستويات الضوضاء في الصف أو الممر باستخدام تطبيق لقياس الديسيبل، وتبحث في امتصاص الصوت وانعكاسه، وتقترح تحسينات عملية لعزل الصوت في المدرسة.", "<b>موجز تطبيقات الموجات فوق الصوتية</b> — يبحث الطلاب في الموجات فوق الصوتية الطبية والسونار وتحديد الموقع بالصدى، ثم يعرضون كيف يتيح الانعكاس والتردد وسرعة الموجة حساب المسافات وتكوين الصور."]}, "Light & Optics": {"support": ["<b>تجربة صندوق الأشعة</b> — يتتبع الطلاب الأشعة الساقطة والمنعكسة على المرايا المستوية باستخدام صندوق الأشعة والمنقلة، مؤكدين أن زاوية السقوط تساوي زاوية الانعكاس.", "<b>بطاقات مخطط الأشعة خطوة بخطوة</b> — تقديم بطاقات مرقّمة توضح كيفية رسم الأشعة الرئيسية الثلاثة للعدسة المحدّبة، ليبني الطلاب المخطط شعاعًا تلو الآخر.", "<b>الانكسار عبر متوازي مستطيلات زجاجي</b> — تتبّع الضوء الداخل إلى متوازي المستطيلات والخارج منه، مع تحديد الأعمدة المقامة واتجاه الانحراف، ثم تلخيص القاعدة باستخدام إطار جملة لملء الفراغ.", "<b>التحقق بمحاكاة PhET Bending Light</b> — يستخدم الطلاب في أزواج محاكاة PhET Bending Light للتنبؤ بكيفية انحراف الشعاع بين الهواء والماء والزجاج، ثم يجيبون عن ثلاثة أسئلة تحقق سريعة."], "extend": ["<b>استقصاء قانون سنل</b> — يقيس الطلاب زوايا السقوط والانكسار لمتوازي مستطيلات زجاجي، ويرسمون sin i مقابل sin r، ويحددون معامل الانكسار من الميل.", "<b>بناء كاميرا الثقب</b> — تبني الفرق كاميرا ثقب أو تلسكوبًا بسيطًا، وتشرح انقلاب الصورة والتكبير وأثر تغيير حجم الثقب أو البعد البؤري للعدسة.", "<b>استقصاء الألياف البصرية</b> — دراسة الانعكاس الكلي الداخلي والزاوية الحرجة باستخدام الليزر وتيار ماء، ثم ربط النتائج بتقنيات الإنترنت في دولة الإمارات والمناظير الطبية.", "<b>دور معلّم البصريات</b> — يُعدّ الطلاب المتمكّنون مقطع فيديو قصيرًا مشروحًا يوضح مخططات الأشعة للعدسات المحدّبة والمقعّرة، ويُنشر على منصة الصف للزملاء الذين يحتاجون إلى المراجعة."]}, "Life Science": {"support": ["<b>بناء نموذج الخلية</b> — يجمّع الطلاب نماذج للخلية النباتية والحيوانية من أجزاء مُعنونة من الورق المقوّى أو الصلصال، ثم يشرحون وظيفة كل عُضيّة لزميل باستخدام بدايات الجمل.", "<b>منظّم أسهم السلسلة الغذائية</b> — استخدام بطاقات مصوّرة لكائنات صحراوية مثل المها وشجرة الغاف لبناء سلاسل غذائية، مع التدرب على اتجاه الأسهم لتوضيح انتقال الطاقة.", "<b>مطابقة أجهزة الجسم</b> — تطابق مجموعات صغيرة بطاقات الأعضاء مع أجهزة الجسم ووظائفها على ملصق كبير لمخطط الجسم، ويصحّح المعلم المفاهيم الخاطئة خلال جولة موجّهة.", "<b>التحقق بترتيب دورة الحياة</b> — يرتّب الطلاب بطاقات مصوّرة لدورات حياة النباتات والحيوانات، ثم يُكملون تحققًا سريعًا على السبورات الصغيرة يحددون فيه كل مرحلة والتغير الرئيسي فيها."], "extend": ["<b>استقصاء بالمجهر</b> — يُعدّ الطلاب شرائح لخلايا البصل وخلايا بطانة الخد، ويرسمون مشاهداتهم بمقياس رسم، ويحسبون التكبير، ويقارنون التراكيب بين الخلايا النباتية والحيوانية في تقرير مختبر.", "<b>دراسة النظام البيئي لأشجار القرم</b> — البحث في أشجار القرم في أبوظبي لبناء شبكة غذائية، ثم التنبؤ بآثار إزالة نوع واحد أو ارتفاع الملوحة على النظام البيئي بأكمله.", "<b>اختبار عادل لنمو النبات</b> — تصميم تجربة مدتها أسبوعان وتنفيذها لاختبار أثر الضوء أو الماء أو التربة على نمو الفول، مع ضبط المتغيرات وعرض النتائج في تمثيل بياني بالخطوط.", "<b>قادة اختبارات علوم الحياة</b> — يكتب الطلاب المتمكّنون اختبار Kahoot حول التكيفات والتصنيف وأجهزة الجسم، ويديرونه للصف، ويشرحون الإجابة الصحيحة بعد كل سؤال."]}, "Physical Science": {"support": ["<b>لعب أدوار حالات المادة</b> — يمثّل الطلاب الجسيمات في المادة الصلبة والسائلة والغازية، فيقتربون أو يتباعدون كلما أضاف المعلم طاقة حرارية أو أزالها.", "<b>محطات بناء الدوائر الكهربائية</b> — تبني مجموعات صغيرة دوائر توالٍ بسيطة باستخدام البطاريات والمصابيح والمفاتيح، وترسم كل دائرة بالرموز القياسية، وتشرح سبب إضاءة المصباح.", "<b>تصنيف الدفع والسحب</b> — تصنيف بطاقات مصوّرة لأفعال يومية ضمن فئات الدفع والسحب والاحتكاك والجاذبية، ثم مناقشة كل منها مع زميل باستخدام بنك المفردات.", "<b>بطاقة الخروج لانتقال الطاقة</b> — يُكمل الطلاب مخططًا قصيرًا لانتقال الطاقة في مصباح يدوي أو غلاية أو سيارة لعبة، محددين الطاقة الداخلة والطاقة الخارجة المفيدة قبل مغادرة الصف."], "extend": ["<b>تحدي التوالي مقابل التوازي</b> — يصمّم الطلاب دوائر تلبي متطلبات محددة، مثل إضاءة غرفة في نموذج منزل بصورة مستقلة، ويفسّرون الفروق في شدة الإضاءة والتيار بالأدلة.", "<b>استقصاء العزل الحراري</b> — تختبر الفرق أي المواد تحافظ على سخونة الماء أطول مدة، وتسجّل درجة الحرارة على فترات، وترسم منحنيات التبريد، وتوصي بمواد لصناديق الغداء في صحراء الإمارات.", "<b>تصميم الآلات البسيطة</b> — بناء نظام رافعة أو بكرة لرفع حمل بأقل جهد، وقياس القوى بميزان نيوتن، وحساب الفائدة الآلية المتحققة.", "<b>محاكاة PhET Energy Skate Park</b> — يستخدم الطلاب المحاكاة لاستكشاف التغيرات في طاقة الحركة وطاقة الوضع، ثم يكتبون أسئلة تنبؤ خاصة بهم ويختبرونها ليجيب عنها زملاؤهم."]}, "Earth & Space Science": {"support": ["<b>نموذج المصباح والكرة الأرضية</b> — يستخدم الطلاب مصباحًا يدويًا ومجسّمًا للكرة الأرضية لتمثيل الليل والنهار والفصول وميل محور الأرض، ويصفون ما يلاحظونه باستخدام أطر الجمل.", "<b>مخطط دورة الصخور</b> — إكمال مخطط انسيابي مدعّم بالصور يربط الصخور النارية والرسوبية والمتحولة بعمليات الانصهار والتجوية والانضغاط والحرارة والضغط.", "<b>نشاط أطوار القمر بالبسكويت</b> — يكشط الطلاب كريمة البسكويت لتمثيل أطوار القمر الثمانية بالترتيب، ويعنونون كل طور، ويشرحون سبب تغيّر الجزء المضاء المرئي.", "<b>التحقق بكيس دورة الماء</b> — صنع كيس محكم الإغلاق لدورة الماء على نافذة مشمسة، وملاحظة التبخر والتكاثف على مدى أيام، وعنونة كل مرحلة على مخطط سريع."], "extend": ["<b>تحليل بيانات الطقس في الإمارات</b> — يحلّل الطلاب بيانات درجات الحرارة والرطوبة الصادرة عن المركز الوطني للأرصاد، ويحددون الأنماط الموسمية، ويفسّرونها بميل محور الأرض ومدارها.", "<b>استقصاء مهمة المريخ</b> — البحث في مشروع الإمارات لاستكشاف المريخ «مسبار الأمل»، وعرض كيف أثّرت الجاذبية والمدار والظروف الكوكبية في تصميمه وتوقيت إطلاقه وأهدافه العلمية.", "<b>نموذج النظام الشمسي بمقياس رسم</b> — حساب المسافات المصغّرة بين الكواكب بمقياس رسم في ممر المدرسة أو الملعب، ثم التأمل في سبب عدم تمثيل رسوم الكتب المدرسية للمقياس الحقيقي للفضاء.", "<b>مختبر نمذجة التعرية</b> — استخدام أحواض الرمل وتدفق الماء لاختبار أثر الانحدار والغطاء النباتي في التعرية، وربط النتائج بفيضانات الأودية وإدارة الأراضي في دولة الإمارات."]}, "Scientific Inquiry & Technology": {"support": ["<b>إطار تخطيط الاختبار العادل</b> — تقديم قالب يتضمن خانات للسؤال والمتغيرات المستقلة والتابعة والمضبوطة، ليخطط الطلاب لتجربة بسيطة مثل اختبار قدرة المناشف الورقية على الامتصاص.", "<b>بطاقات تصنيف المتغيرات</b> — تصنّف مجموعات صغيرة بطاقات تصف خصائص التجربة إلى: ما نغيّره، وما نقيسه، وما نُبقيه ثابتًا، مع تغذية راجعة من المعلم.", "<b>دعامة مهارات التمثيل البياني</b> — استخدام محاور مرسومة مسبقًا بتدريجات موجّهة ليمثّل الطلاب نتائجهم بأنفسهم، ثم يجيبوا عن ثلاثة أسئلة منظّمة حول الاتجاه الظاهر في تمثيلهم البياني.", "<b>بدايات جمل الفرضية</b> — التدرب على كتابة تنبؤات قابلة للاختبار باستخدام الإطار «إذا غيّرتُ…، فإن… سوف…، لأن…»، مع التحقق على السبورات الصغيرة لتقديم تغذية راجعة فورية."], "extend": ["<b>مشروع الاستقصاء المفتوح</b> — يختار الطلاب سؤالهم الخاص، ويخططون لاختبار عادل وينفذونه، ويحللون البيانات بقراءات متكررة، ويقيّمون الموثوقية في عرض ملصق علمي.", "<b>استقصاء بمسجّل البيانات</b> — استخدام مستشعرات الحرارة أو الضوء أو الصوت مع جهاز لوحي لجمع بيانات آنية، ثم تفسير اتجاهات التمثيل البياني والنتائج الشاذة في تقرير قصير.", "<b>تحدي التصميم الهندسي</b> — تصمّم الفرق حلًا لمشكلة محلية مثل مبرّد ماء يعمل بالطاقة الشمسية وتبنيه وتختبره، مع تطوير التصاميم بناءً على نتائج الاختبار المقيسة.", "<b>لجنة مراجعة الأقران</b> — يراجع الطلاب المتمكّنون خطط تجارب زملائهم باستخدام قائمة تحقق للمتغيرات والسلامة والصدق، ثم يقدّمون نقطتي قوة واقتراحًا واحدًا للتحسين لكل خطة."]}, "Matter & Atomic Structure": {"support": ["<b>عُدد بناء الذرة</b> — يبني الطلاب نماذج بور لأول عشرين عنصرًا باستخدام خرز ملوّن للبروتونات والنيوترونات والإلكترونات، ثم يتحققون من توزيع المستويات مقارنةً بالجدول الدوري.", "<b>جدول الجسيمات دون الذرية</b> — إكمال منظّم مدعّم يوضح الشحنة والكتلة النسبية وموقع البروتونات والنيوترونات والإلكترونات، ثم حساب أعدادها من العدد الذري والعدد الكتلي.", "<b>محاكاة PhET Build an Atom</b> — يستخدم الطلاب في أزواج محاكاة PhET Build an Atom لتكوين ذرات متعادلة وأيونات ونظائر، مع تسجيل أثر كل تغيير في الشحنة والعدد الكتلي.", "<b>التحقق من النظائر بالسبورات الصغيرة</b> — يعرض المعلم رموز النظائر ويكتب الطلاب أعداد البروتونات والنيوترونات والإلكترونات على السبورات الصغيرة لتقديم تغذية راجعة تكوينية فورية وإعادة التدريس."], "extend": ["<b>تحدي الكتلة الذرية النسبية</b> — يحسب الطلاب الكتل الذرية النسبية من بيانات وفرة النظائر، ثم يعملون عكسيًا لإيجاد نسب الوفرة المجهولة من نتائج مطياف الكتلة المعطاة.", "<b>الخط الزمني للنماذج الذرية</b> — البحث في أعمال دالتون وطومسون ورذرفورد وبور وتشادويك، ثم إعداد خط زمني يوضح الأدلة التي أدت إلى تعديل كل نموذج أو استبداله.", "<b>استقصاء التدرج في خواص الجدول الدوري</b> — تحليل بيانات نصف القطر الذري وطاقة التأين والسالبية الكهربائية، ورسم تمثيلات بيانية عبر الدورات والمجموعات، وتفسير التدرج باستخدام الحجب الإلكتروني والشحنة النووية.", "<b>قيادة مختبر اختبار اللهب</b> — يدير الطلاب المتمكّنون تجربة اختبار اللهب، ويربطون الألوان الملاحظة بمستويات طاقة الإلكترونات، ويشرحون أطياف الانبعاث لمجموعتهم في المختبر."]}, "Bonding & Compounds": {"support": ["<b>دعامة النقطة والتقاطع</b> — تقديم قوالب لمستويات الطاقة الخارجية ليرسم الطلاب مخططات النقطة والتقاطع لـ NaCl وMgO وH2O وCO2، باتباع قائمة تحقق خطوة بخطوة مع تغذية راجعة من المعلم.", "<b>بطاقات شحنات الأيونات</b> — يجمع الطلاب بطاقات الكاتيونات والأنيونات كقطع الأحجية حتى تتوازن الشحنات، ثم يكتبون الصيغة الكيميائية الصحيحة لكل مركب أيوني ناتج.", "<b>تصنيف أنواع الروابط</b> — تصنّف مجموعات صغيرة المركبات إلى أيونية وتساهمية وفلزية باستخدام مخطط انسيابي قائم على اتحاد الفلزات واللافلزات، مع تبرير كل تصنيف شفهيًا.", "<b>عُدد النماذج الجزيئية</b> — بناء جزيئات تساهمية بسيطة مثل الميثان والأمونيا والماء باستخدام عُدد النماذج، وعدّ أزواج الإلكترونات المشتركة، ورسم الأشكال الناتجة."], "extend": ["<b>مختبر التنبؤ بالخواص</b> — يختبر الطلاب درجة الانصهار والذوبانية والتوصيل الكهربائي لمواد صلبة مجهولة، ثم يحددون نوع الرابطة في كل منها ويبرّرون استنتاجاتهم بالتركيب والترابط.", "<b>تحدي أشكال VSEPR</b> — التنبؤ بأشكال جزيئات مثل SF6 وPCl5 وNH4+ وزوايا الروابط فيها، وبنائها باستخدام العُدد ومحاكاة PhET Molecule Shapes.", "<b>استقصاء القوى بين الجزيئية</b> — مقارنة درجات غليان الألكانات والكحولات وهاليدات الهيدروجين، وتفسير الأنماط من خلال قوى لندن والتجاذب ثنائي القطب–ثنائي القطب والروابط الهيدروجينية.", "<b>موجز علوم المواد</b> — البحث في الجرافين أو الألماس أو المواد النانوية، ثم عرض كيف يفسّر الترابط والتركيب خواصها وتطبيقاتها الفعلية في الصناعة والتكنولوجيا في دولة الإمارات."]}, "Reactions & Stoichiometry": {"support": ["<b>موازنة المعادلات بالمحسوسات</b> — يستخدم الطلاب بلاطات ذرات ملوّنة لموازنة المعادلات بصورة محسوسة، مع عدّ الذرات في كل طرف قبل كتابة المعاملات في المعادلة الرمزية.", "<b>منظّم خريطة المول</b> — تقديم خريطة طريق بصرية للمول تربط الكتلة وعدد المولات وعدد الجسيمات وحجم الغاز، مع أسهم مرمّزة بالألوان توضح متى يُضرب ومتى يُقسم.", "<b>التلاشي التدريجي للأمثلة المحلولة</b> — عرض حل نموذجي كامل لعمليتين حسابيتين لكتل المواد المتفاعلة، ثم حذف خطوة في كل مرة حتى يُكمل الطلاب مسائل النسب المولية باستقلالية مع تغذية راجعة فورية.", "<b>التحقق بمحاكاة PhET للموازنة</b> — يُكمل الطلاب في أزواج لعبة PhET Balancing Chemical Equations، ويسجّلون المستويات التي بلغوها، ويشرحون معادلة وجدوها صعبة في بطاقة الخروج."], "extend": ["<b>تجربة المردود المئوي</b> — ينفّذ الطلاب تفاعل ترسيب أو تحضير أكسيد المغنيسيوم، ويحسبون المردود النظري والمردود المئوي، ويقيّمون مصادر فقد الناتج في التجربة.", "<b>تحدي المادة المحدِّدة للتفاعل</b> — حل مسائل متعددة الخطوات حول المادة المحدِّدة والمادة الفائضة، ثم تصميم تشبيه بوصفة طعام يشرح المفهوم للطلاب الأصغر سنًا في الصف.", "<b>تحليل المعايرة</b> — إجراء معايرة حمض–قاعدة، وحساب التركيز المجهول باستخدام النسب المولية، وتقييم الدقة من خلال النتائج المتوافقة ونسبة عدم اليقين المئوية.", "<b>دراسة حالة في الكيمياء الصناعية</b> — البحث في الاقتصاد الذري والمردود في صناعة إماراتية مثل إنتاج الأمونيا أو الألومنيوم في شركة الإمارات العالمية للألمنيوم (EGA)، مع التوصية بتحسينات تجعل العملية أكثر استدامة."]}, "States, Solutions & Organic": {"support": ["<b>تجربة منحنى التسخين</b> — يسخّن الطلاب الجليد حتى الغليان مع تسجيل درجة الحرارة كل 30 ثانية، ثم يعنونون المناطق المستوية في تمثيلهم البياني بالانصهار والغليان.", "<b>دعامة بصرية للتركيز</b> — استخدام كؤوس تحتوي على أعداد مختلفة من مكعبات السكر المذابة لتمثيل التركيز، ثم التدرب على حسابات mol/dm³ باستخدام مثلث الصيغة وقائمة تحقق للوحدات.", "<b>منظّم السلاسل المتجانسة</b> — إكمال جدول لأول ستة ألكانات وألكينات يتضمن الأسماء والصيغ والمخططات البنائية، مع إبراز نمط CH2 المتكرر.", "<b>بطاقات المجموعات الوظيفية</b> — يختبر الطلاب في أزواج بعضهم بعضًا باستخدام Quizizz أو البطاقات التعليمية لتحديد مجموعات الألكين والكحول والحمض الكربوكسيلي، ويعيد المعلم تدريس أخطاء التسمية الشائعة."], "extend": ["<b>استقصاء منحنى الذوبانية</b> — يقيس الطلاب ذوبانية نترات البوتاسيوم عند درجات حرارة مختلفة، ويرسمون منحنى الذوبانية، ويستخدمونه للتنبؤ بكتل البلورات المترسبة عند التبريد.", "<b>تحدي بناء المتشكّلات</b> — استخدام عُدد النماذج الجزيئية لبناء جميع المتشكّلات البنائية لـ C5H12 وC4H8 وتسميتها، مع تفسير الفروق في درجات الغليان.", "<b>استقصاء قوانين الغازات</b> — استخدام محاكاة PhET Gas Properties لاشتقاق قانوني بويل وشارل، ثم تطبيق معادلة الغاز المثالي على سيناريوهات مناخية حقيقية في دولة الإمارات.", "<b>موجز بحثي في البتروكيماويات</b> — البحث في التقطير التجزيئي والتكسير في مصفاة إماراتية مثل مصفاة الرويس، وعرض العلاقة بين طول السلسلة الهيدروكربونية واستخدامات الوقود."]}, "Chemistry of Life": {"support": ["<b>بطاقات مطابقة الوحدات البنائية</b> — يطابق الطلاب في أزواج كل بطاقة جزيء كبير بوحدته البنائية ووظيفته ومثال غذائي عليه، ثم يتحققون من الإجابات بمفتاح مرمّز بالألوان.", "<b>محطة شرائط الرقم الهيدروجيني</b> — يختبر الطلاب خمسة سوائل منزلية بورق الرقم الهيدروجيني (pH)، ويضعون كلًا منها على مقياس pH كبير على الأرض قبل تسجيل النتائج.", "<b>نموذج القفل والمفتاح</b> — يستخدم الطلاب أشكالًا ورقية مقصوصة للإنزيم والمادة المتفاعلة لتوضيح التخصص وكيف تغيّر الحرارة شكل الموقع النشط.", "<b>أطر الجمل</b> — تقديم أطر مثل «الماء مذيب جيد لأن …» لمساعدة الطلاب على كتابة تفسيرات قصيرة باستخدام المفردات الرئيسية."], "extend": ["<b>تصميم استقصاء الإنزيمات</b> — يخطط الطلاب لاختبار عادل لأثر درجة الحرارة أو الرقم الهيدروجيني في نشاط إنزيم الكاتاليز، مع تحديد المتغيرات والتنبؤ بشكل التمثيل البياني.", "<b>تحليل مخطط الطاقة</b> — يرسم الطلاب تمثيلات بيانية للتفاعل بوجود الإنزيم وبدونه ويُضيفون عليها شروحًا، مفسّرين سبب تغيّر طاقة التنشيط مع ثبات التغير الكلي في الطاقة.", "<b>دراسة حالة نقص الإنزيم</b> — يبحث الطلاب في عدم تحمّل اللاكتوز ويشرحون كيف يسبّب غياب إنزيم ما ظهور الأعراض، رابطين التركيب بالوظيفة.", "<b>تحدي المحلول المنظِّم</b> — يقارن الطلاب تغيّر الرقم الهيدروجيني عند إضافة حمض إلى الماء مقابل إضافته إلى محلول منظِّم، ويشرحون كيف تحافظ المحاليل المنظِّمة في الدم على الاتزان الداخلي."]}, "Cells & Energy": {"support": ["<b>بطاقات وظائف العُضيّات</b> — يطابق الطلاب بطاقات العُضيّات بأدوار وظيفية في مصنع، مثل الميتوكوندريا بوصفها محطة توليد الطاقة، ثم يعنونون مخططًا للخلية.", "<b>عرض الأسموزية بالبيض</b> — يلاحظ الطلاب بيضًا منزوع القشرة في الماء وفي الشراب السكري، ويسجّلون التغيرات في الكتلة، ويصفونها باستخدام مصطلحي منخفض التوتر ومرتفع التوتر.", "<b>أحجية المعادلات</b> — يرتّب الطلاب بطاقات مقصوصة للمواد المتفاعلة والناتجة لبناء معادلتي البناء الضوئي والتنفس الخلوي، ثم يقارنون بينهما جنبًا إلى جنب.", "<b>دليل خطوات استخدام المجهر</b> — قائمة تحقق مصوّرة ترشد الطلاب إلى ضبط البؤرة وحساب التكبير الكلي قبل فحص خلايا البصل وخلايا بطانة الخد."], "extend": ["<b>استقصاء المساحة السطحية</b> — يقيس الطلاب زمن الانتشار في مكعبات أجار بأحجام مختلفة، ويفسّرون سبب انقسام الخلايا بدلًا من استمرارها في النمو.", "<b>تدقيق ناتج ATP</b> — يتتبع الطلاب جزيئات ATP وNADH وFADH₂ عبر التحلل السكري ودورة كريبس وسلسلة نقل الإلكترونات لتبرير الناتج الصافي.", "<b>مناظرة C4 مقابل CAM</b> — يناقش الطلاب أي المسارين أنسب لنباتات صحراء الإمارات، مستخدمين أدلة حول الثغور وفقد الماء وتثبيت الكربون.", "<b>تصميم نموذج الغشاء</b> — يبني الطلاب نموذج الفسيفساء المائع موضحين البروتينات والكوليسترول والكربوهيدرات، ثم يعرضون كيف يدعم كل جزء عملية النقل."]}, "Human Body & Health": {"support": ["<b>عنونة خريطة الجسم</b> — يضع الطلاب بطاقات أسماء الأعضاء على مخطط للجسم بالحجم الطبيعي، مع ترميز كل عضو بلون جهازه، ثم يشرحون وظيفة عضو واحد لزميل.", "<b>جولة مسار الدم</b> — يسير الطلاب على مخطط أرضي للقلب والرئتين، ذاكرين كل حجرة وصمام ووعاء دموي بالترتيب الصحيح.", "<b>أطر حلقة التغذية الراجعة</b> — يُكمل الطلاب مخططًا انسيابيًا مملوءًا جزئيًا لتنظيم درجة حرارة الجسم باستخدام كلمات: المنبّه، والمستقبِل، ومركز التحكم، والمستجيب.", "<b>بطاقات المفردات</b> — يختبر الطلاب في أزواج بعضهم بعضًا ببطاقات مصوّرة للمصطلحات الرئيسية مثل الحويصلات الهوائية والنيفرون والتشابك العصبي والجسم المضاد."], "extend": ["<b>ملف حالة مرضية</b> — يشخّص الطلاب حالة مريض افتراضي من الأعراض ونتائج الفحوصات، موضحين الجهاز المصاب وموصين بالعلاج.", "<b>تحليل بيانات الكلية</b> — يقارن الطلاب مستويات الجلوكوز والبروتين واليوريا في الدم والراشح والبول، ثم يفسّرون ما يكشفه كل فرق عن وظيفة النيفرون.", "<b>شرح اللقاحات</b> — يُعدّ الطلاب نشرة توعوية قصيرة في الصحة العامة تشرح المناعة المجتمعية والاستجابتين المناعيتين الأولية والثانوية، مع تمثيل بياني مُعنون.", "<b>استقصاء آثار العقاقير</b> — يبحث الطلاب في كيفية تأثير الكافيين أو النيكوتين في التشابكات العصبية، ويقدّمون نصائح قائمة على الأدلة للمراهقين."]}, "Plants & Ecology": {"support": ["<b>الترميز اللوني للأنسجة</b> — يلوّن الطلاب الأنسجة الجلدية والأساسية والوعائية على مخططات مقاطع عرضية للجذر والساق والورقة باستخدام مفتاح ألوان موحّد.", "<b>عرض الكرفس والصبغة</b> — يضع الطلاب الكرفس في ماء ملوّن، ثم يقطعون مقاطع منه لرؤية الخشب المصبوغ ووصف عملية نقل الماء.", "<b>رسم منحنى النمو</b> — يمثّل الطلاب بيانات سكانية معطاة على شبكة مدعّمة، ويعنونون مرحلة النمو الأسي وخط القدرة الاستيعابية.", "<b>مطابقة جدار الكلمات</b> — يطابق الطلاب في أزواج كلمات رئيسية مثل الثغور والخشب والكثافة والعامل المحدِّد بالصور والتعريفات المبسّطة."], "extend": ["<b>بحث التكيّف الصحراوي</b> — يقارن الطلاب تكيّفات أوراق أشجار الغاف ونخيل التمر، رابطين الثغور والأدمة والجذور بالمحافظة على الماء في دولة الإمارات.", "<b>محاكاة الوسم وإعادة الأسر</b> — يقدّر الطلاب حجم مجتمع من حبوب الفول باستخدام طريقة الوسم وإعادة الأسر، ويحسبون التقدير ويقيّمون مصادر الخطأ.", "<b>مناظرة السكان البشريين</b> — يستخدم الطلاب مخططات التركيب العمري لدولتين للتنبؤ بالنمو المستقبلي ومناقشة أثره في الموارد.", "<b>مشروع النباتات الطبية</b> — يبحث الطلاب في دواء مشتق من النبات مثل الأسبرين، ويشرحون أي نسيج نباتي ينتج المركّب الفعّال."]}, "Genetics & Heredity": {"support": ["<b>الوراثة بقذف العملات</b> — يقذف الطلاب في أزواج عملتين بوصفهما أبوين متباينَي اللواقح، ويسجّلون الطرز الجينية لـ 40 فردًا من الأبناء، ويقارنون نتائجهم بتنبؤ مربع بانيت.", "<b>قوالب مربع بانيت</b> — يُكمل الطلاب شبكات مملوءة جزئيًا كُتبت فيها الأمشاج مسبقًا، ثم ينتقلون إلى شبكات فارغة عندما يكتسبون الثقة.", "<b>نموذج DNA بالخرز</b> — يبني الطلاب شريطًا قصيرًا من DNA بخرز ملوّن، ثم يكوّنون الشريط المكمّل ونسخة mRNA.", "<b>مفتاح رموز سجل النسب</b> — يستخدم الطلاب مفتاح رموز مطبوعًا لتلوين سجل نسب عائلي بسيط وتحديد الأفراد الحاملين والمصابين."], "extend": ["<b>محقّق سجل النسب</b> — يحلّل الطلاب سجلات نسب غير مُعنونة ويبرّرون ما إذا كانت كل صفة جسمية سائدة أو جسمية متنحية أو مرتبطة بالكروموسوم X، مستشهدين بأفراد محددين.", "<b>الطريقة المختصرة لاحتمالات التهجين الثنائي</b> — يستخدم الطلاب قاعدة الضرب لحل مسائل التهجين الثلاثي، ويتحققون من إحدى الإجابات بمربع بانيت كامل.", "<b>تحليل آثار الطفرات</b> — يطبّق الطلاب طفرات الاستبدال والإضافة والحذف على تسلسل جيني معطى، ويستخدمون جدول الكودونات للتنبؤ بالتغير في كل بروتين.", "<b>ندوة أخلاقيات التقنية الحيوية</b> — يبحث الطلاب في الهندسة الوراثية أو تحديد تسلسل الجينوم، ويناقشون فوائدها ومخاطرها الأخلاقية مستخدمين الأدلة العلمية."]}};
